_enterprise_agents_cache: list[dict] = []
_enterprise_agents_fetch_lock = asyncio.Lock()
_background_tasks: set = set()


class _EnterpriseAgentDirectoryUnavailable(Exception):
    """企业智能体目录当前不可作为权威快照。"""


def _spawn_background(coro) -> "asyncio.Task":
    """创建后台任务并持有引用，避免被 GC 回收或异常丢失。"""
    task = asyncio.create_task(coro)
    _background_tasks.add(task)
    task.add_done_callback(_background_tasks.discard)
    return task


def _get_installed_enterprise_agent_ids() -> set[str]:
    """获取本地已安装的企业智能体 ID 集合（不含 ent_ 前缀）。"""
    try:
        from ..enterprise.state import SyncStateStore

        store = SyncStateStore()
        installed = store.get_all_installed_agents()
        return set(installed.keys())
    except Exception:
        return set()


def _is_enterprise_workspace_ready(workspace_dir: str, agent_id: str) -> bool:
    """企业智能体的 workspace/agent.json 是否已真正落盘且内容可用。

    只要 agent_id 出现在 config.json 的 profiles 里就无条件 installed=True，
    会把"config.json 已注册但 agent.json 还没写完"的半安装态也呈现成可选中
    的正常条目——点了也选不中（诊断"智能体无法被选中"时定位，见
    installer.py 里 save_agent_config_to_workspace 与 _register_agent_to_config
    的写入顺序注释）。

    只查 exists() 不够：写入中途被打断也会留下一个存在但为空/半截 JSON 的
    文件（2026-07-17 review 指出，config.py 的 _atomic_write_agent_config 已
    改成原子写堵住新写入的这个口子，但这里仍需按"能否被解析"判断，覆盖历史
    遗留的半截文件）。调用方必须在 load_agent_config 之前用这个函数判断：
    它对缺失/无效的 agent.json 会自愈补写占位配置，届时文件已经"存在"，
    检查就失去意义。

    只查 JSON 语法同样不够：``{}`` 这类语法合法但缺 id/name 的内容照样能过
    ``json.load()``，随后 ``load_agent_config()`` 的 ``model_validate`` 抛
    ValidationError，最终仍被报成 installed=True（2026-07-17 review 复现）。
    因此这里按调用方真正要走的模型校验判断，并核对 id 与 agent_id 一致——
    id 对不上说明该文件属于别的智能体，同样不算就绪。
    """
    try:
        agent_config_path = Path(workspace_dir).expanduser() / "agent.json"
        with open(agent_config_path, "r", encoding="utf-8") as f:
            raw = json.load(f)
        agent_config = AgentProfileConfig.model_validate(raw)
    except Exception:
        return False
    return agent_config.id == agent_id


class AgentSummary(BaseModel):
    """Agent summary information."""

    id: str
    name: str
    description: str
    workspace_dir: str
    enabled: bool
    active_model: ModelSlotConfig | None = None
    source: str = "custom"
    installed: bool = True
    update_available: bool = False
    enterprise_id: str | None = None


class AgentListResponse(BaseModel):
    """Response for listing agents."""

    agents: list[AgentSummary]


class CustomAgentItem(BaseModel):
    """自定义智能体精简信息（仅 id 和名称）。"""

    id: str
    name: str


class CustomAgentListResponse(BaseModel):
    """自定义智能体列表响应。"""

    agents: list[CustomAgentItem]


class ReorderAgentsRequest(BaseModel):
    """Request model for persisting agent order."""

    agent_ids: list[str]


class CreateAgentRequest(BaseModel):
    """Request model for creating a new agent.

    The ``id`` field is optional.  When provided the server uses it as
    the agent identifier (after sanitization); when omitted a random
    short UUID is generated automatically.
    """

    id: str | None = None
    name: str
    description: str = ""
    workspace_dir: str | None = None
    language: str | None = None
    skill_names: list[str] | None = None
    active_model: ModelSlotConfig | None = None
    prompt_agents: str | None = None
    prompt_soul: str | None = None
    prompt_profile: str | None = None

    @field_validator("id", mode="before")
    @classmethod
    def sanitize_id(cls, value: str | None) -> str | None:
        """Strip whitespace from the custom ID."""
        if value is None:
            return None
        if isinstance(value, str):
            sanitized = sanitize_agent_id(value)
            return sanitized if sanitized else None
        return value

    @field_validator("workspace_dir", mode="before")
    @classmethod
    def strip_workspace_dir(cls, value: str | None) -> str | None:
        """Strip accidental whitespace"""
        if value is None:
            return None
        if isinstance(value, str):
            stripped = value.strip()
            return stripped if stripped else None
        return value


def _get_multi_agent_manager(request: Request) -> "MultiAgentManager":
    """Get MultiAgentManager from app state."""
    if not hasattr(request.app.state, "multi_agent_manager"):
        raise HTTPException(
            status_code=500,
            detail="MultiAgentManager not initialized",
        )
    return request.app.state.multi_agent_manager


def _normalized_agent_order(config) -> list[str]:
    """Return a deduplicated agent order covering every configured agent."""
    profile_ids = list(config.agents.profiles.keys())
    ordered_ids: list[str] = []

    for agent_id in config.agents.agent_order:
        if agent_id in config.agents.profiles and agent_id not in ordered_ids:
            ordered_ids.append(agent_id)

    for agent_id in profile_ids:
        if agent_id not in ordered_ids:
            ordered_ids.append(agent_id)

    return ordered_ids


def _read_profile_description(workspace_dir: str) -> str:
    """Read description from PROFILE.md if exists."""
    try:
        profile_path = Path(workspace_dir) / "PROFILE.md"
        if not profile_path.exists():
            return ""

        content = read_text_file_with_encoding_fallback(profile_path).strip()
        lines = []
        in_identity = False

        for line in content.split("\n"):
            if line.strip().startswith("## 身份") or line.strip().startswith(
                "## Identity",
            ):
                in_identity = True
                continue
            if in_identity:
                if line.strip().startswith("##"):
                    break
                if line.strip() and not line.strip().startswith("#"):
                    lines.append(line.strip())

        return " ".join(lines)[:200] if lines else ""
    except Exception:  # noqa: E722
        return ""


def _stop_disabled_enterprise_agent(
    agent_id: str,
    request: Request | None,
) -> None:
    """管理端已禁用的企业智能体：停掉本地仍在跑的实例（尽力而为）。"""
    if request is None:
        return
    try:
        manager = _get_multi_agent_manager(request)
        if agent_id in manager.agents:
            _spawn_background(manager.stop_agent(agent_id))
            logger.info("企业智能体已禁用，停止实例: %s", agent_id)
    except Exception:
        pass


def _summarize_half_installed_agent(
    agent_id: str,
    agent_ref: AgentProfileRef,
    source: str,
    enterprise_id: str | None,
    remote_ent_map: dict,
) -> AgentSummary:
    """workspace 尚未写完的企业智能体条目。

    绝不能碰 load_agent_config()——它会当场自愈写一份占位 agent.json，把这次
    installed=False 变成下一次刷新时的假 installed=True（2026-07-17 review 用
    真实两连续 list_agents() 调用复现：第一次 installed=False，自愈落盘后第二
    次就变 True 了）。名称/描述改用管理端目录数据兜底，不碰本地半成品
    workspace。
    """
    remote = remote_ent_map.get(enterprise_id) if enterprise_id else None
    return AgentSummary(
        id=agent_id,
        name=(
            (remote.name if remote and remote.name else "") or agent_id.title()
        ),
        description=(
            remote.description if remote and remote.description else ""
        ),
        workspace_dir=agent_ref.workspace_dir,
        enabled=getattr(agent_ref, "enabled", True),
        active_model=None,
        source=source,
        installed=False,
        update_available=False,
        enterprise_id=enterprise_id,
    )


def _summarize_installed_agent(
    agent_id: str,
    agent_ref: AgentProfileRef,
    source: str,
    enterprise_id: str | None,
    remote_ent_map: dict,
) -> AgentSummary:
    """已就绪的智能体条目（读本地 agent.json + PROFILE.md 描述）。"""
    agent_config = load_agent_config(agent_id)
    description = agent_config.description or ""

    profile_desc = _read_profile_description(agent_ref.workspace_dir)
    if profile_desc:
        if description.strip():
            description = f"{description.strip()} | {profile_desc}"
        else:
            description = profile_desc

    update_available = False
    remote = None
    if source == "enterprise" and enterprise_id:
        local_version_no = getattr(agent_ref, "enterprise_version_no", None)
        remote = remote_ent_map.get(enterprise_id)
        if remote and remote.version_no is not None:
            update_available = (
                local_version_no is None
                or remote.version_no > local_version_no
            )

    # 名称鲁棒性兜底：本地 name 为空、或恰好等于 agent_id.title()（自愈占位名
    # 的形态，见 config.py load_agent_config 的历史遗留数据）时，优先用管理
    # 端真实名称回填，避免占位名永久显示成 id
    # （.agentdocs/workflow/260730-enterprise-install-slow-and-id-name.md 节 H）。
    # 判据必须是精确相等，不能用 startswith 等模糊匹配——用户真把智能体命名
    # 成 "Ent_Xxx" 时不该被覆盖；remote_ent_map 为空（ED 不可达）时已有的正
    # 常本地名称也绝不能被抹成空。回落顺序：远端真名 → 本地 name → id。
    display_name = agent_config.name
    is_placeholder_name = (
        not display_name or display_name == agent_id.title()
    )
    if is_placeholder_name and remote and remote.name:
        display_name = remote.name
    if not display_name:
        display_name = agent_id

    return AgentSummary(
        id=agent_id,
        name=display_name,
        description=description,
        workspace_dir=agent_ref.workspace_dir,
        enabled=getattr(agent_ref, "enabled", True),
        active_model=agent_config.active_model,
        source=source,
        # 走到这里说明 source != enterprise，或者 enterprise 分支已在调用方的
        # workspace 就绪检查里分流掉了未就绪的情况——能到达此处的企业智能体
        # 必然已就绪。
        installed=True,
        update_available=update_available,
        enterprise_id=enterprise_id,
    )


def _summarize_agent_fallback(
    agent_id: str,
    agent_ref: AgentProfileRef,
) -> AgentSummary:
    """归一化过程中抛异常时的兜底条目，保证列表不整体塌掉。"""
    fallback_source = getattr(agent_ref, "source", "custom")
    return AgentSummary(
        id=agent_id,
        name=(
            DEFAULT_AGENT_DISPLAY_NAME
            if agent_id == "default"
            else agent_id.title()
        ),
        description="",
        workspace_dir=agent_ref.workspace_dir,
        enabled=getattr(agent_ref, "enabled", True),
        source=fallback_source,
        installed=(
            fallback_source != "enterprise"
            or _is_enterprise_workspace_ready(
                agent_ref.workspace_dir,
                agent_id,
            )
        ),
        update_available=False,
        # 之前这里漏传，企业智能体走进异常兜底分支时 enterprise_id 会丢失
        # ——前端的安装/更新按钮靠这个字段发起同步请求（2026-07-17 review
        # 指出）。
        enterprise_id=getattr(agent_ref, "enterprise_id", None),
    )


def _summarize_configured_agent(
    agent_id: str,
    agent_ref: AgentProfileRef,
    remote_ent_map: dict,
    disabled_ent_ids: set,
    request: Request | None,
) -> AgentSummary | None:
    """把一条已注册 profile 归一成列表条目。

    Returns:
        列表条目；返回 None 表示该智能体已被管理端禁用或删除，不出现在列表里。
    """
    try:
        source = getattr(agent_ref, "source", "custom")
        enterprise_id = getattr(agent_ref, "enterprise_id", None)

        if (
            source == "enterprise"
            and enterprise_id
            and enterprise_id in disabled_ent_ids
        ):
            _stop_disabled_enterprise_agent(agent_id, request)
            return None

        # 管理端已删除（远端列表不再返回）：与禁用一样立即从列表消失，
        # 本地文件由 _cleanup_removed_enterprise_agents 异步清理。
        # 仅当 remote_ent_map 非空时判断：fetch 失败返回空列表时不能误判
        # 所有已安装企业智能体为已删除而全部隐藏。
        if (
            source == "enterprise"
            and enterprise_id
            and remote_ent_map
            and enterprise_id not in remote_ent_map
        ):
            return None

        # 必须在 load_agent_config 之前判断：它对缺失/无效的 agent.json 会
        # 自愈补写占位配置，届时文件已经"存在"，事后检查形同虚设。
        if source == "enterprise" and not _is_enterprise_workspace_ready(
            agent_ref.workspace_dir,
            agent_id,
        ):
            return _summarize_half_installed_agent(
                agent_id,
                agent_ref,
                source,
                enterprise_id,
                remote_ent_map,
            )

        return _summarize_installed_agent(
            agent_id,
            agent_ref,
            source,
            enterprise_id,
            remote_ent_map,
        )
    except Exception:  # noqa: E722
        return _summarize_agent_fallback(agent_id, agent_ref)


def _remote_only_enterprise_agents(
    enterprise_agents: list,
    local_ids: set,
) -> list:
    """管理端有、本地未安装且未禁用的企业智能体（列表里显示为可安装）。"""
    summaries = []
    for ent_agent in enterprise_agents:
        local_id = f"ent_{ent_agent.id}"
        if local_id in local_ids or bool(ent_agent.disable_flag):
            continue
        summaries.append(
            AgentSummary(
                id=local_id,
                name=ent_agent.name or "",
                description=ent_agent.description or "",
                workspace_dir="",
                enabled=True,
                active_model=None,
                source="enterprise",
                installed=False,
                update_available=False,
                enterprise_id=ent_agent.id,
            ),
        )
    return summaries


def _cleanup_removed_enterprise_agents(
    remote_ent_ids: set,
    request: Request | None,
) -> None:
    """管理端已删除的企业智能体：异步卸载本地残留（尽力而为）。"""
    for ent_id in _get_installed_enterprise_agent_ids():
        if ent_id in remote_ent_ids:
            continue

        logger.info("企业智能体已从管理端删除，异步卸载: %s", ent_id)
        try:
            engine = (
                getattr(request.app.state, "sync_engine", None)
                if request is not None
                else None
            )
            if engine is None:
                logger.warning("同步引擎未初始化，跳过卸载: %s", ent_id)
            else:
                _spawn_background(engine.remove_agent(ent_id))
        except Exception as e:
            logger.warning("触发卸载企业智能体失败: %s, %s", ent_id, e)


@router.get(
    "",
    response_model=AgentListResponse,
    summary="List all agents",
    description=(
        "Get list of all configured agents including enterprise" " agents"
    ),
)
async def list_agents(
    request: Request = None,
    force_refresh: bool = False,
) -> AgentListResponse:
    """List all configured agents including enterprise agents."""
    global _enterprise_agents_cache
    config = load_config()
    ordered_agent_ids = _normalized_agent_order(config)

    # 普通页面加载继续复用短缓存；只有用户明确点击刷新时才直读管理端。
    # false 分支不传参数，兼容现有测试与扩展里无参数的目录桩函数。
    snapshot_authoritative = True
    try:
        enterprise_agents = (
            await _fetch_enterprise_agents(force_refresh=True)
            if force_refresh
            else await _fetch_enterprise_agents()
        )
    except _EnterpriseAgentDirectoryUnavailable:
        # 网络/登录状态异常时用 last-good 快照展示，且绝不能据此执行删除。
        snapshot_authoritative = False
        enterprise_agents = list(_enterprise_agents_cache)
    else:
        _enterprise_agents_cache = enterprise_agents

    disabled_ent_ids = {a.id for a in enterprise_agents if a.disable_flag}
    remote_ent_map = {a.id: a for a in enterprise_agents}

    agents = []
    for agent_id in ordered_agent_ids:
        summary = _summarize_configured_agent(
            agent_id,
            config.agents.profiles[agent_id],
            remote_ent_map,
            disabled_ent_ids,
            request,
        )
        if summary is not None:
            agents.append(summary)

    local_ids = {a.id for a in agents}
    agents.extend(
        _remote_only_enterprise_agents(enterprise_agents, local_ids),
    )

    # 待安装（installed=False，含半安装态与远端未安装）始终置顶，两列表均适用；
    # 已安装区内部保持 agent_order 顺序（default 仍打头），不扰动现有序。
    agents = [a for a in agents if a.installed is False] + [
        a for a in agents if a.installed is not False
    ]

    # 只有管理端成功返回的权威快照才能驱动删除。不可达、退出登录或 SSO
    # 尚未就绪都不能被解释成“远端已删除全部 Agent”。
    if snapshot_authoritative:
        _cleanup_removed_enterprise_agents(set(remote_ent_map), request)

    return AgentListResponse(agents=agents)


async def _fetch_enterprise_agents(
    force_refresh: bool = False,
) -> list[dict]:
    """获取企业智能体列表；手动刷新时跳过短缓存。"""
    import time

    cache_key = "_enterprise_agents_cache"
    cache_expiry_key = "_enterprise_agents_cache_expiry"
    cache_duration = 10

    # 远端请求与缓存读写必须串行：否则先发的普通请求可能在强刷之后完成，
    # 用旧快照反向覆盖新缓存，甚至触发错误清理。
    async with _enterprise_agents_fetch_lock:
        if not hasattr(_fetch_enterprise_agents, cache_key):
            setattr(_fetch_enterprise_agents, cache_key, None)
            setattr(_fetch_enterprise_agents, cache_expiry_key, 0)

        cache = getattr(_fetch_enterprise_agents, cache_key)
        expiry = getattr(_fetch_enterprise_agents, cache_expiry_key)

        if not force_refresh and cache is not None and time.time() < expiry:
            return cache

        try:
            from ..enterprise.client import EnterpriseClient

            client = EnterpriseClient()
            if not client.is_enabled():
                raise _EnterpriseAgentDirectoryUnavailable(
                    "企业智能体同步未启用",
                )

            agents = await client.fetch_agent_list()

            setattr(_fetch_enterprise_agents, cache_key, agents)
            setattr(
                _fetch_enterprise_agents,
                cache_expiry_key,
                time.time() + cache_duration,
            )

            return agents
        except _EnterpriseAgentDirectoryUnavailable as e:
            if force_refresh:
                raise HTTPException(
                    status_code=503,
                    detail=str(e),
                ) from e
            raise
        except Exception as e:
            logger.warning("获取企业智能体列表失败: %s", e)
            if force_refresh:
                raise HTTPException(
                    status_code=502,
                    detail="刷新企业智能体列表失败",
                ) from e
            raise _EnterpriseAgentDirectoryUnavailable(
                "获取企业智能体列表失败",
            ) from e


@router.put(
    "/order",
    summary="Persist agent order",
    description="Save the full ordered list of configured agent IDs",
)
async def reorder_agents(
    reorder_request: ReorderAgentsRequest = Body(...),
) -> dict:
    """Persist the full ordered list of agent IDs."""
    config = load_config()
    configured_ids = list(config.agents.profiles.keys())

    if len(reorder_request.agent_ids) != len(set(reorder_request.agent_ids)):
        raise HTTPException(
            status_code=400,
            detail="Each configured agent ID must appear exactly once.",
        )

    if set(reorder_request.agent_ids) != set(configured_ids):
        raise HTTPException(
            status_code=400,
            detail="Each configured agent ID must appear exactly once.",
        )

    config.agents.agent_order = list(reorder_request.agent_ids)
    save_config(config)

    return {"success": True, "agent_ids": config.agents.agent_order}


@router.get(
    "/custom",
    response_model=CustomAgentListResponse,
    summary="List custom agents",
    description="Get list of custom agents with id and name only",
)
async def list_custom_agents() -> CustomAgentListResponse:
    """列出所有自定义智能体（仅返回 id 和名称）。"""
    config = load_config()
    ordered_agent_ids = _normalized_agent_order(config)

    agents: list[CustomAgentItem] = []
    for agent_id in ordered_agent_ids:
        agent_ref = config.agents.profiles.get(agent_id)
        if agent_ref is None:
            continue
        source = getattr(agent_ref, "source", "custom")
        if source != "custom":
            continue
        try:
            agent_config = load_agent_config(agent_id)
            name = agent_config.name
        except Exception:  # noqa: E722
            name = (
                DEFAULT_AGENT_DISPLAY_NAME
                if agent_id == "default"
                else agent_id.title()
            )
        agents.append(CustomAgentItem(id=agent_id, name=name))

    return CustomAgentListResponse(agents=agents)


class OptimizeAgentPromptRequest(BaseModel):
    prompt: str


def _sse_data(payload: dict) -> str:
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"


@router.post(
    "/optimize-prompt/stream",
    summary="优化自定义智能体提示词",
    description="转发管理端 optimize-prompt，SSE 返回拆好的三段",
)
async def optimize_agent_prompt_stream(
    request: OptimizeAgentPromptRequest = Body(...),
):
    """一键优化：不落盘、不创建智能体。"""
    prompt = (request.prompt or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt 不能为空")

    async def generate():
        from ..enterprise.client import (
            EnterpriseAuthError,
            EnterpriseBadRequest,
            EnterpriseClient,
            EnterpriseUnavailable,
        )
        from ..prompt_sections import split_optimize_prompt

        accumulated: list[str] = []
        try:
            client = EnterpriseClient()
            if not client.is_enabled():
                yield _sse_data({"error": "未登录或管理端不可用"})
                return
            async for event in client.stream_optimize_prompt(prompt):
                kind = event.get("kind")
                if kind == "text":
                    text = event.get("text") or ""
                    if text:
                        accumulated.append(text)
                        yield _sse_data({"text": text})
                elif kind == "error":
                    yield _sse_data(
                        {"error": event.get("message") or "提示词优化失败"},
                    )
                    return
                elif kind == "complete":
                    combined = "".join(accumulated)
                    parts = split_optimize_prompt(combined)
                    if not parts:
                        logger.warning(
                            "优化结果无法拆成三段，原文前 400 字: %s",
                            combined[:400],
                        )
                        yield _sse_data(
                            {
                                "error": "优化结果无法拆成 AGENTS/SOUL/PROFILE 三段，请重试",
                            },
                        )
                        return
                    agents, soul, profile = parts
                    yield _sse_data(
                        {
                            "done": True,
                            "prompt_agents": agents,
                            "prompt_soul": soul,
                            "prompt_profile": profile,
                        },
                    )
                    return
            yield _sse_data({"error": "优化未完成，请重试"})
        except EnterpriseAuthError as exc:
            yield _sse_data({"error": str(exc)})
        except EnterpriseBadRequest as exc:
            yield _sse_data({"error": str(exc)})
        except EnterpriseUnavailable as exc:
            yield _sse_data({"error": str(exc)})
        except Exception:
            logger.exception("智能体提示词优化失败")
            yield _sse_data({"error": "提示词优化失败，请重试"})

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


@router.get(
    "/{agentId}",
    response_model=AgentProfileConfig,
    summary="Get agent details",
    description="Get complete configuration for a specific agent",
)
async def get_agent(agentId: str = PathParam(...)) -> AgentProfileConfig:
    """Get agent configuration."""
    try:
        agent_config = load_agent_config(agentId)
        return agent_config
    except (ValueError, app_base_exception_type()) as e:
        raise HTTPException(status_code=404, detail=str(e)) from e
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


def _generate_unique_id(existing_ids: set[str]) -> str:
    """Generate a unique random short agent ID.

    Raises:
        HTTPException: If a unique ID could not be generated.
    """
    max_attempts = 10
    for _ in range(max_attempts):
        candidate_id = generate_short_agent_id()
        if candidate_id not in existing_ids:
            return candidate_id
    raise HTTPException(
        status_code=500,
        detail="Failed to generate unique agent ID after 10 attempts",
    )


def _complete_prompt_files(request: CreateAgentRequest) -> dict[str, str] | None:
    """三个字段都空则不覆盖模板；只带一部分则 400。"""
    agents = (request.prompt_agents or "").strip()
    soul = (request.prompt_soul or "").strip()
    profile = (request.prompt_profile or "").strip()
    if not agents and not soul and not profile:
        return None
    if not agents or not soul or not profile:
        raise HTTPException(
            status_code=400,
            detail="prompt_agents、prompt_soul、prompt_profile 必须同时提供",
        )
    return {
        "prompt_agents": agents,
        "prompt_soul": soul,
        "prompt_profile": profile,
    }


def _rollback_failed_agent_workspace(workspace_dir: Path) -> None:
    """创建失败时清掉刚建的工作区，避免半成品目录。"""
    try:
        remove_agent_workspace_dir(workspace_dir)
    except Exception:
        logger.warning("创建失败，清理工作区未完成: %s", workspace_dir, exc_info=True)


@router.post(
    "",
    response_model=AgentProfileRef,
    status_code=201,
    summary="Create new agent",
    description="Create a new agent with optional custom ID",
)
async def create_agent(
    request: CreateAgentRequest = Body(...),
) -> AgentProfileRef:
    """Create a new agent.

    When ``request.id`` is provided, it is used as the agent identifier
    (validated for URL-safe characters, length, reserved words, and
    uniqueness).  Otherwise a random short UUID is generated.
    """
    config = load_config()
    existing_ids = set(config.agents.profiles.keys())

    if request.id:
        try:
            validate_agent_id(request.id, existing_ids)
        except ValueError as e:
            raise HTTPException(
                status_code=400,
                detail=str(e),
            ) from e
        new_id = request.id
    else:
        new_id = _generate_unique_id(existing_ids)

    prompt_files = _complete_prompt_files(request)

    if request.workspace_dir:
        # 自填工作区目录必须落在 WORKING_DIR/workspaces/<id> 之下。此处历史上
        # 零路径校验（只 strip 空白后直接 mkdir），用户可把工作区指向
        # ~/.eazybot/memory 这类全局共享目录甚至 WORKING_DIR 自身，随后带
        # purge_workspace 的删除就会把它整个 rmtree；删除侧守卫已收紧，创建侧
        # 同口径校验才是根治（否则仍会往共享目录里写一整套 agent 骨架文件）。
        try:
            workspace_dir = resolve_workspace_dir_within_working_dir(
                request.workspace_dir,
            )
        except ValueError as exc:
            raise HTTPException(
                status_code=400,
                detail=str(exc),
            ) from exc
    else:
        workspace_dir = Path(
            f"{WORKING_DIR}/workspaces/{new_id}",
        ).expanduser()

    workspace_preexisted = workspace_dir.exists()
    workspace_dir.mkdir(parents=True, exist_ok=True)

    from ...config.config import (
        ChannelConfig,
        MCPConfig,
        HeartbeatConfig,
        ToolsConfig,
    )
    from ..enterprise.installer import _write_prompt_files

    language = normalize_agent_language(
        request.language or config.agents.language or "zh",
    )

    agent_config = AgentProfileConfig(
        id=new_id,
        name=request.name,
        description=request.description,
        workspace_dir=str(workspace_dir),
        language=language,
        channels=ChannelConfig(),
        mcp=MCPConfig(),
        heartbeat=HeartbeatConfig(),
        tools=ToolsConfig(),
        active_model=request.active_model,
    )

    registered = False
    try:
        _initialize_agent_workspace(
            workspace_dir,
            skill_names=(
                request.skill_names if request.skill_names is not None else []
            ),
            language=language,
        )

        if prompt_files:
            _write_prompt_files(workspace_dir, prompt_files)

        if not request.skill_names:
            _bind_builtin_skills_to_workspace(workspace_dir)

        agent_ref = AgentProfileRef(
            id=new_id,
            workspace_dir=str(workspace_dir),
            enabled=True,
        )

        config.agents.profiles[new_id] = agent_ref
        config.agents.agent_order = _normalized_agent_order(config)
        save_config(config)
        registered = True
        save_agent_config(new_id, agent_config)
    except HTTPException:
        if registered:
            config.agents.profiles.pop(new_id, None)
            try:
                save_config(config)
            except Exception:
                logger.warning("创建失败，回滚 config.json 未完成: %s", new_id)
        if not workspace_preexisted:
            _rollback_failed_agent_workspace(workspace_dir)
        raise
    except Exception as exc:
        if registered:
            config.agents.profiles.pop(new_id, None)
            try:
                save_config(config)
            except Exception:
                logger.warning("创建失败，回滚 config.json 未完成: %s", new_id)
        if not workspace_preexisted:
            _rollback_failed_agent_workspace(workspace_dir)
        logger.exception("创建智能体失败: %s", new_id)
        raise HTTPException(
            status_code=500,
            detail=f"创建智能体失败: {exc}",
        ) from exc

    logger.info(f"Created new agent: {new_id} (name={request.name})")

    _report_operate_log_async(
        agent_id=new_id,
        content=f"创建自定义智能体【{request.name}】",
    )

    return agent_ref


def _reject_enterprise_mutation(
    agent_ref: AgentProfileRef,
    action: str,
) -> None:
    """企业智能体由管理端统一下发，本地不允许改动。

    技能域（skills.py）与 MCP 域（mcp.py）已有同类守卫，此处补齐
    智能体本体，避免绕过前端直接调 API 改/删/启停企业智能体。
    """
    if getattr(agent_ref, "source", "custom") == "enterprise":
        raise HTTPException(
            status_code=403,
            detail=f"企业智能体由管理端统一管理，不允许{action}",
        )


@router.put(
    "/{agentId}",
    response_model=AgentProfileConfig,
    summary="Update agent",
    description="Update agent configuration and trigger reload",
)
async def update_agent(
    agentId: str = PathParam(...),
    agent_config: AgentProfileConfig = Body(...),
    request: Request = None,
) -> AgentProfileConfig:
    """Update agent configuration."""
    config = load_config()

    if agentId not in config.agents.profiles:
        raise HTTPException(
            status_code=404,
            detail=f"Agent '{agentId}' not found",
        )

    _reject_enterprise_mutation(config.agents.profiles[agentId], "编辑")

    existing_config = load_agent_config(agentId)

    # id 与 workspace_dir 一律不受编辑接口摆布：
    #  - id 是主键，由路径参数决定；
    #  - workspace_dir 的真源是 config.json 的 AgentProfileRef（创建/迁移时
    #    写入），agent.json 里这份只是副本。但它并非死字段——command_handler
    #    的 /dump_history 落盘路径与 CLI task 的 workspace 基址都读它，前端
    #    编辑态那个 disabled 输入框的值仍会随 PUT 一起提交，一旦回填为空就会
    #    把它覆盖成空串（Path("") == Path(".")，落盘落到进程 cwd）。
    update_data = agent_config.model_dump(exclude_unset=True)
    for key, value in update_data.items():
        if key not in ("id", "workspace_dir"):
            setattr(existing_config, key, value)

    existing_config.id = agentId
    save_agent_config(agentId, existing_config)
    schedule_agent_reload(request, agentId)

    _report_operate_log_async(
        agent_id=agentId,
        content=f"编辑自定义智能体【{existing_config.name}】",
    )

    return agent_config


@router.delete(
    "/{agentId}",
    summary="Delete agent",
    description=(
        "Delete agent config; optionally purge its workspace directory "
        "via purge_workspace (cannot delete default agent)"
    ),
)
async def delete_agent(
    agentId: str = PathParam(...),
    purge_workspace: bool = Body(False, embed=True),
    request: Request = None,
) -> dict:
    """Delete an agent, optionally purging its workspace directory."""
    # 江南定制：智能体默认禁止删除（防误删已配置的智能体）。
    # 企业智能体的上下架走企业同步（不走此 API），不受影响。
    # 如确需开放，设置 EAZYBOT_AGENT_DELETE_BLOCKED=0。
    import os as _os

    if _os.environ.get("EAZYBOT_AGENT_DELETE_BLOCKED", "1").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }:
        raise HTTPException(
            status_code=403,
            detail="智能体不可删除（已由管理员禁用）",
        )
    config = load_config()

    if agentId not in config.agents.profiles:
        raise HTTPException(
            status_code=404,
            detail=f"Agent '{agentId}' not found",
        )

    if agentId == "default":
        raise HTTPException(
            status_code=400,
            detail="Cannot delete the default agent",
        )

    _reject_enterprise_mutation(config.agents.profiles[agentId], "删除")

    workspace_dir = config.agents.profiles[agentId].workspace_dir

    agent_name = agentId
    try:
        agent_config = load_agent_config(agentId)
        if agent_config and agent_config.name:
            agent_name = agent_config.name
    except Exception:
        pass

    manager = _get_multi_agent_manager(request)
    await manager.stop_agent(agentId)

    del config.agents.profiles[agentId]
    config.agents.agent_order = _normalized_agent_order(config)
    save_config(config)

    workspace_removed = False
    # 清空工作区失败必须回报给调用方：守卫只认
    # <WORKING_DIR>/workspaces/<agentId>，存量把 workspace_dir 指到别处的
    # 智能体一律会被拒；此处若只写日志，接口仍是 success=true，前端就会对
    # 一个「勾了不可恢复、实际没删」的操作提示删除成功。
    workspace_purge_failed = False
    if purge_workspace and workspace_dir:
        try:
            workspace_removed = remove_agent_workspace_dir(
                workspace_dir,
                expected_agent_id=agentId,
            )
        except ValueError as exc:
            workspace_purge_failed = True
            logger.warning(
                "Skip purging workspace for agent '%s': %s",
                agentId,
                exc,
            )
        except OSError as exc:
            workspace_purge_failed = True
            logger.error(
                "Failed to purge workspace for agent '%s': %s",
                agentId,
                exc,
            )

    _report_operate_log_async(
        agent_id=agentId,
        content=(
            f"删除自定义智能体【{agent_name}】"
            + ("（含工作区文件）" if workspace_removed else "")
            + ("（工作区文件清理失败）" if workspace_purge_failed else "")
        ),
    )

    return {
        "success": True,
        "agent_id": agentId,
        "workspace_removed": workspace_removed,
        "workspace_purge_failed": workspace_purge_failed,
    }


@router.patch(
    "/{agentId}/toggle",
    summary="Toggle agent enabled state",
    description="Enable or disable an agent (cannot disable default agent)",
)
async def toggle_agent_enabled(
    agentId: str = PathParam(...),
    enabled: bool = Body(..., embed=True),
    request: Request = None,
) -> dict:
    """Toggle agent enabled state."""
    config = load_config()

    if agentId not in config.agents.profiles:
        raise HTTPException(
            status_code=404,
            detail=f"Agent '{agentId}' not found",
        )

    if agentId == "default":
        raise HTTPException(
            status_code=400,
            detail="Cannot disable the default agent",
        )

    agent_ref = config.agents.profiles[agentId]
    _reject_enterprise_mutation(agent_ref, "启用或禁用")

    manager = _get_multi_agent_manager(request)

    if not enabled and getattr(agent_ref, "enabled", True):
        await manager.stop_agent(agentId)

    agent_ref.enabled = enabled
    save_config(config)

    if enabled:
        try:
            await manager.get_agent(agentId)
            logger.info(f"Agent {agentId} started successfully")
        except Exception as e:
            logger.error(f"Failed to start agent {agentId}: {e}")
            raise HTTPException(
                status_code=500,
                detail=f"Agent enabled but failed to start: {str(e)}",
            ) from e

    return {
        "success": True,
        "agent_id": agentId,
        "enabled": enabled,
    }


def _apply_workspace_md_templates(
    workspace_dir: Path,
    language: str,
    *,
    md_template_id: str | None,
) -> None:
    """Copy common and template-specific markdown files for a workspace."""
    copy_workspace_md_files(
        language,
        workspace_dir,
        md_template_id=md_template_id,
    )


def _ensure_heartbeat_file(workspace_dir: Path, language: str) -> None:
    """Create the default HEARTBEAT.md if it is missing."""
    heartbeat_file = workspace_dir / "HEARTBEAT.md"
    if heartbeat_file.exists():
        return

    default_heartbeat_mds = {
        "zh": """# Heartbeat checklist
- 扫描收件箱紧急邮件
- 查看未来 2h 的日历
- 检查待办是否卡住
- 若安静超过 8h，轻量 check-in
""",
        "en": """# Heartbeat checklist
- Scan inbox for urgent email
- Check calendar for next 2h
- Check tasks for blockers
- Light check-in if quiet for 8h
""",
        "ru": """# Heartbeat checklist
- Проверить входящие на срочные письма
- Просмотреть календарь на ближайшие 2 часа
- Проверить задачи на наличие блокировок
- Лёгкая проверка при отсутствии активности более 8 часов
""",
    }
    heartbeat_content = default_heartbeat_mds.get(
        language,
        default_heartbeat_mds["en"],
    )
    with open(heartbeat_file, "w", encoding="utf-8") as file:
        file.write(heartbeat_content.strip())


def _install_initial_skills(
    workspace_dir: Path,
    skill_names: list[str] | None,
) -> None:
    """Install requested initial skills from the skill pool."""
    if not skill_names:
        return

    pool_service = SkillPoolService()
    for skill_name in skill_names:
        try:
            result = pool_service.download_to_workspace(
                skill_name=skill_name,
                workspace_dir=workspace_dir,
                overwrite=False,
            )
            if result.get("success"):
                continue
            logger.warning(
                "Failed to install initial skill %s for %s: %s",
                skill_name,
                workspace_dir,
                result.get("reason", "unknown"),
            )
        except Exception as e:
            logger.warning(
                "Failed to install initial skill %s for %s: %s",
                skill_name,
                workspace_dir,
                e,
            )


def _bind_builtin_skills_to_workspace(workspace_dir: Path) -> None:
    """直接从打包源码绑定所有内置技能到 workspace，绕过技能池。

    新建自定义/企业智能体时调用。从打包的内置技能目录选取符合当前
    语言偏好的变体，原子拷贝到 workspace/skills/，并写入 workspace
    manifest（source=builtin + builtin_language + version_text）。
    不再调用 import_builtin_skills / SkillPoolService.download_to_workspace，
    因此不会污染技能池，也不依赖池是否已初始化。
    """
    registry = _get_packaged_builtin_registry()
    if not registry:
        logger.debug("没有打包的内置技能需要绑定")
        return

    preferred_language = get_builtin_skill_language_preference()
    workspace_skills_dir = get_workspace_skills_dir(workspace_dir)
    workspace_skills_dir.mkdir(parents=True, exist_ok=True)
    workspace_manifest = read_skill_manifest(workspace_dir)
    existing_skills = workspace_manifest.get("skills", {})

    bound_count = 0
    for skill_name in sorted(registry):
        variant = _select_builtin_variant(
            registry,
            skill_name,
            preferred_language=preferred_language,
        )
        if variant is None:
            logger.debug("内置技能 %s 没有可用变体，跳过", skill_name)
            continue

        target_dir = workspace_skills_dir / skill_name
        if target_dir.exists() or skill_name in existing_skills:
            logger.debug(
                "跳过绑定内置技能 %s: workspace 已存在同名技能",
                skill_name,
            )
            continue

        try:
            with _staged_skill_dir(skill_name) as staged_dir:
                _copy_skill_dir(variant.skill_dir, staged_dir)
                _scan_skill_dir_or_raise(staged_dir, skill_name)
                _copy_skill_dir(staged_dir, target_dir)

            metadata = _build_skill_metadata(
                skill_name,
                target_dir,
                source="builtin",
                protected=False,
            )

            def _update(payload: dict[str, Any]) -> None:
                payload.setdefault("skills", {})
                payload["skills"][skill_name] = {
                    "enabled": True,
                    "channels": ["all"],
                    "source": "builtin",
                    "config": {},
                    "metadata": metadata,
                    "requirements": metadata["requirements"],
                    "updated_at": metadata["updated_at"],
                    "builtin_language": variant.language,
                }

            _mutate_json(
                get_workspace_skill_manifest_path(workspace_dir),
                _default_workspace_manifest(),
                _update,
            )
            bound_count += 1
        except Exception as e:
            logger.warning("绑定内置技能 %s 失败: %s", skill_name, e)

    logger.info(
        "已绑定 %d 个内置技能到 workspace %s（直拷打包源码，未走技能池）",
        bound_count,
        workspace_dir,
    )


def _initialize_agent_workspace(
    workspace_dir: Path,
    skill_names: list[str] | None = None,
    md_template_id: str | None = None,
    language: str | None = None,
) -> None:
    """Initialize agent workspace with only explicitly requested skills."""
    from ...config import load_config as load_global_config

    (workspace_dir / "sessions").mkdir(exist_ok=True)
    (workspace_dir / "memory").mkdir(exist_ok=True)
    get_workspace_skills_dir(workspace_dir).mkdir(exist_ok=True)

    config = load_global_config()
    if not language:
        language = config.agents.language or "zh"

    _apply_workspace_md_templates(
        workspace_dir,
        language,
        md_template_id=md_template_id,
    )
    _ensure_heartbeat_file(workspace_dir, language)
    _install_initial_skills(workspace_dir, skill_names)

    jobs_file = workspace_dir / "jobs.json"
    if not jobs_file.exists():
        with open(jobs_file, "w", encoding="utf-8") as file:
            json.dump(
                {"version": 1, "jobs": []},
                file,
                ensure_ascii=False,
                indent=2,
            )

    chats_file = workspace_dir / "chats.json"
    if not chats_file.exists():
        with open(chats_file, "w", encoding="utf-8") as file:
            json.dump(
                {"version": 1, "chats": []},
                file,
                ensure_ascii=False,
                indent=2,
            )
